"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowLeft, CheckCircle2, Loader2, Plus, Store, ShieldCheck } from "lucide-react";
import { createClient } from "@/lib/supabase/client";

type StoreRow={id:string;public_id:string|null;name:string;slug:string;description:string|null;status:string;verification_status:string;verification_badge:boolean;created_at:string};

export default function VendorStoresPage(){
  const supabase=createClient();
  const [rows,setRows]=useState<StoreRow[]>([]); const [name,setName]=useState(""); const [description,setDescription]=useState(""); const [editing,setEditing]=useState<string|null>(null); const [loading,setLoading]=useState(true); const [saving,setSaving]=useState(false); const [busy,setBusy]=useState<string|null>(null); const [error,setError]=useState(""); const [success,setSuccess]=useState("");
  async function load(){setLoading(true);setError("");const{data:{user}}=await supabase.auth.getUser();if(!user){window.location.href="/login?next=/vendor/stores";return}const{data,error:e}=await supabase.from("stores").select("id,public_id,name,slug,description,status,verification_status,verification_badge,created_at").eq("owner_user_id",user.id).order("created_at",{ascending:false});if(e)setError(e.message);else setRows((data||[]) as StoreRow[]);setLoading(false)}
  useEffect(()=>{load()},[]);
  function reset(){setName("");setDescription("");setEditing(null)}
  function beginEdit(row:StoreRow){setEditing(row.id);setName(row.name);setDescription(row.description||"");setSuccess("");setError("")}
  async function save(){setSaving(true);setError("");setSuccess("");const{data:{user}}=await supabase.auth.getUser();if(!user){setError("Please sign in again.");setSaving(false);return}if(name.trim().length<2){setError("Store name must be at least 2 characters.");setSaving(false);return}const slugBase=name.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");const slug=editing?`${slugBase}-${editing.slice(0,8)}`:`${slugBase}-${crypto.randomUUID().slice(0,8)}`;const payload={name:name.trim(),slug,description:description.trim()||null};const result=editing?await supabase.from("stores").update(payload).eq("id",editing).eq("owner_user_id",user.id):await supabase.from("stores").insert({...payload,owner_user_id:user.id,status:"draft"}).select("id").single();if(result.error){setError(result.error.message);setSaving(false);return}setSuccess(editing?"Store updated.":"Store created.");reset();await load();setSaving(false)}
  async function requestVerification(id:string){setBusy(id);setError("");setSuccess("");const{error:e}=await supabase.rpc("submit_store_for_verification",{store_input:id,verification_type_input:"professional_store"});if(e)setError(e.message);else{setSuccess("Store verification request submitted.");await load()}setBusy(null)}
  return <main className="mx-auto max-w-6xl px-4 py-7 sm:px-6 lg:px-8"><Link href="/vendor" className="inline-flex items-center gap-2 text-sm text-[var(--muted)]"><ArrowLeft size={16}/> Vendor Center</Link><div className="mt-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-semibold uppercase tracking-widest text-[var(--muted)]">Vendor Center</p><h1 className="mt-1 text-3xl font-semibold">My stores</h1><p className="mt-2 text-sm text-[var(--muted)]">Create and manage your storefronts using DRIGHT&apos;s existing store, verification and listing infrastructure.</p></div><button onClick={reset} className="inline-flex items-center justify-center gap-2 rounded-xl bg-[var(--primary)] px-4 py-3 text-sm font-semibold text-[var(--background)]"><Plus size={17}/> New store</button></div>
    <section className="mt-6 rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5 sm:p-6"><h2 className="font-semibold">{editing?"Edit store":"Create a store"}</h2><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="text-sm font-medium">Store name<input value={name} onChange={e=>setName(e.target.value)} maxLength={120} placeholder="Your store name" className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm outline-none"/></label><label className="text-sm font-medium">Description<input value={description} onChange={e=>setDescription(e.target.value)} maxLength={500} placeholder="What does your store offer?" className="mt-2 w-full rounded-xl border border-[var(--border)] bg-[var(--background)] px-3 py-3 text-sm outline-none"/></label></div><div className="mt-4 flex flex-wrap gap-2"><button onClick={save} disabled={saving} className="inline-flex items-center gap-2 rounded-xl bg-[var(--primary)] px-4 py-2.5 text-sm font-semibold text-[var(--background)] disabled:opacity-60">{saving&&<Loader2 size={15} className="animate-spin"/>}{editing?"Save changes":"Create store"}</button>{editing&&<button onClick={reset} className="rounded-xl border border-[var(--border)] px-4 py-2.5 text-sm font-semibold">Cancel</button>}</div>{error&&<div className="mt-4 rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div>}{success&&<div className="mt-4 flex items-center gap-2 rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-700"><CheckCircle2 size={16}/>{success}</div>}</section>
    <section className="mt-6 space-y-3">{loading?<div className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-8 text-sm text-[var(--muted)]">Loading stores…</div>:rows.length===0?<div className="rounded-2xl border border-dashed border-[var(--border)] bg-[var(--surface)] p-10 text-center"><Store size={32} className="mx-auto"/><h2 className="mt-4 font-semibold">No stores yet</h2><p className="mt-2 text-sm text-[var(--muted)]">Create a store to organize your DRIGHT listings.</p></div>:rows.map(row=><article key={row.id} className="rounded-2xl border border-[var(--border)] bg-[var(--surface)] p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><div className="flex flex-wrap items-center gap-2"><h2 className="text-lg font-semibold">{row.name}</h2>{row.verification_badge&&<span className="inline-flex items-center gap-1 rounded-full border border-[var(--border)] px-2 py-1 text-[11px] font-semibold"><ShieldCheck size={12}/> Verified</span>}<span className="rounded-full border border-[var(--border)] px-2 py-1 text-[11px] font-semibold">{row.status.replaceAll("_"," ")}</span></div><p className="mt-2 text-xs text-[var(--muted)]">{row.public_id||row.id} · verification: {row.verification_status.replaceAll("_"," ")}</p>{row.description&&<p className="mt-3 text-sm text-[var(--muted)]">{row.description}</p>}</div><div className="flex flex-wrap gap-2"><button onClick={()=>beginEdit(row)} className="rounded-xl border border-[var(--border)] px-3 py-2 text-xs font-semibold">Edit</button>{["not_requested","rejected"].includes(row.verification_status)&&<button onClick={()=>requestVerification(row.id)} disabled={busy===row.id} className="inline-flex items-center gap-2 rounded-xl border border-[var(--border)] px-3 py-2 text-xs font-semibold disabled:opacity-60">{busy===row.id&&<Loader2 size={13} className="animate-spin"/>}Request verification</button>}</div></div></article>)}</section>
  </main>
}
